const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const adj = Array.from({ length: n + 1 }, () => []);
for (let e = 0; e < m; e++) {
  const u = tok[2 + 2 * e], v = tok[3 + 2 * e];
  adj[u].push([v, e]);
  adj[v].push([u, e]);
}
const tin = new Array(n + 1).fill(-1), low = new Array(n + 1).fill(0);
const bridges = [];
let timer = 0;
function dfs(v, parentEdge) {
  tin[v] = low[v] = timer++;
  for (const [to, e] of adj[v]) {
    if (e === parentEdge) continue;
    if (tin[to] !== -1) {
      low[v] = Math.min(low[v], tin[to]);
    } else {
      dfs(to, e);
      low[v] = Math.min(low[v], low[to]);
      if (low[to] > tin[v]) bridges.push(e + 1);
    }
  }
}
for (let s = 1; s <= n; s++) if (tin[s] === -1) dfs(s, -1);
bridges.sort((x, y) => x - y);
console.log([bridges.length, ...bridges].join("\n"));

