#include <bits/stdc++.h>
using namespace std;

vector<vector<pair<int, int>>> adj;
vector<int> tin, low, bridges;
int timer_ = 0;

void dfs(int v, int parentEdge) {
    tin[v] = low[v] = timer_++;
    for (auto [to, e] : adj[v]) {
        if (e == parentEdge) continue;
        if (tin[to] != -1) {
            low[v] = min(low[v], tin[to]);
        } else {
            dfs(to, e);
            low[v] = min(low[v], low[to]);
            if (low[to] > tin[v]) bridges.push_back(e + 1);
        }
    }
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    adj.assign(n + 1, {});
    for (int e = 0; e < m; e++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back({v, e});
        adj[v].push_back({u, e});
    }
    tin.assign(n + 1, -1);
    low.assign(n + 1, 0);
    for (int s = 1; s <= n; s++) if (tin[s] == -1) dfs(s, -1);
    sort(bridges.begin(), bridges.end());
    printf("%d\n", (int)bridges.size());
    for (int b : bridges) printf("%d\n", b);
    return 0;
}
